        for i in range(H):
            if G[i][j]:
                if cnt == 0:
                    cnt = 1
                    continue
                if cnt == 1:
                    continue
                if cnt == 2:
                    return -1
            else:
                if cnt == 0:
                    continue
                cnt = 2
        if cnt == 0:
            zw = 1
    if zw^zh:
        return -1
    ans = 0
    used = set()
    geta = W
    for i in range(H):
        for j in range(W):
            if G[i][j] == 0:
                continue
            if (i*geta + j) in used:
                continue
            ans += 1
            stack = [i*geta + j]
            while stack:
                nh, nw = divmod(stack.pop(), geta)
                for dh, dw in DIREC:
