                    if not 0 <= fh < H or not 0 <= fw < W:
                        continue
                    if not G[fh][fw]:
                        continue
                    vf = fh*geta + fw
                    if vf in used:
                        continue
                    stack.append(vf)
                    used.add(vf)
    return ans
